BEGIN TRANSACTION;


INSERT INTO gpkg_geometry_columns
VALUES('locality_point','geometry','POINT',4326,1,0);


INSERT INTO gpkg_extensions
VALUES('locality_point','geometry','gpkg_rtree_index','http://www.geopackage.org/spec120/#extension_rtree','write-only');


INSERT INTO gpkg_contents
VALUES('locality_point','features','locality_point','Locality where observations are made.','2023-09-15T13:21:52.679Z',NULL,NULL,NULL,NULL,4326);


CREATE TABLE IF NOT EXISTS "locality_point" (
    "fid" INTEGER NOT NULL,
    "uuid" TEXT NOT NULL UNIQUE,
    "field_project_fuid" TEXT NOT NULL,
    "name" TEXT NOT NULL UNIQUE,
    "locality_type_code"  TEXT NOT NULL,
    "locality_description" TEXT,
    "map_face_note" TEXT,
    "geology_description" TEXT,
    "recorded_by" TEXT NOT NULL,
    "recorded_on" DATETIME NOT NULL,
    "geometry" POINT NOT NULL,
    FOREIGN KEY("locality_type_code") REFERENCES "dic_locality_type"("code"),
    FOREIGN KEY("field_project_fuid") REFERENCES "field_project"("uuid"),
    PRIMARY KEY("fid" AUTOINCREMENT)
);

PRAGMA writable_schema=ON;


INSERT INTO sqlite_schema(type, name, tbl_name, rootpage, sql)
VALUES('table','rtree_locality_point_geometry','rtree_locality_point_geometry',0,'CREATE VIRTUAL TABLE "rtree_locality_point_geometry" USING rtree(id, minx, maxx, miny, maxy)');


CREATE TABLE IF NOT EXISTS "rtree_locality_point_geometry_rowid"(rowid INTEGER PRIMARY KEY,
  nodeno);


CREATE TABLE IF NOT EXISTS "rtree_locality_point_geometry_node"(nodeno INTEGER PRIMARY KEY,
  data);


INSERT INTO rtree_locality_point_geometry_node
VALUES(1,X'');


CREATE TABLE IF NOT EXISTS "rtree_locality_point_geometry_parent"(nodeno INTEGER PRIMARY KEY,
  parentnode);


CREATE TRIGGER "rtree_locality_point_geometry_insert" AFTER
INSERT ON "locality_point" WHEN (new."geometry" NOT NULL
  AND NOT ST_IsEmpty(NEW."geometry")) BEGIN
INSERT
OR
REPLACE INTO "rtree_locality_point_geometry"
VALUES (NEW."fid",ST_MinX(NEW."geometry"), ST_MaxX(NEW."geometry"),ST_MinY(NEW."geometry"),
  ST_MaxY(NEW."geometry")); END;


CREATE TRIGGER "rtree_locality_point_geometry_update1" AFTER
UPDATE OF "geometry" ON "locality_point" WHEN OLD."fid" = NEW."fid"
AND (NEW."geometry" NOTNULL
  AND NOT ST_IsEmpty(NEW."geometry")) BEGIN
INSERT
OR
REPLACE INTO "rtree_locality_point_geometry"
VALUES (NEW."fid",ST_MinX(NEW."geometry"), ST_MaxX(NEW."geometry"),ST_MinY(NEW."geometry"),
  ST_MaxY(NEW."geometry")); END;


CREATE TRIGGER "rtree_locality_point_geometry_update2" AFTER
UPDATE OF "geometry" ON "locality_point" WHEN OLD."fid" = NEW."fid"
AND (NEW."geometry" ISNULL
  OR ST_IsEmpty(NEW."geometry")) BEGIN
DELETE
FROM "rtree_locality_point_geometry"
WHERE id = OLD."fid"; END;


CREATE TRIGGER "rtree_locality_point_geometry_update3" AFTER
UPDATE ON "locality_point" WHEN OLD."fid" != NEW."fid"
AND (NEW."geometry" NOTNULL
  AND NOT ST_IsEmpty(NEW."geometry")) BEGIN
DELETE
FROM "rtree_locality_point_geometry"
WHERE id = OLD."fid";
  INSERT
  OR
  REPLACE INTO "rtree_locality_point_geometry"
VALUES (NEW."fid",ST_MinX(NEW."geometry"), ST_MaxX(NEW."geometry"),ST_MinY(NEW."geometry"),
  ST_MaxY(NEW."geometry")); END;


CREATE TRIGGER "rtree_locality_point_geometry_update4" AFTER
UPDATE ON "locality_point" WHEN OLD."fid" != NEW."fid"
AND (NEW."geometry" ISNULL
  OR ST_IsEmpty(NEW."geometry")) BEGIN
DELETE
FROM "rtree_locality_point_geometry"
WHERE id IN (OLD."fid", NEW."fid"); END;


CREATE TRIGGER "rtree_locality_point_geometry_delete" AFTER
DELETE ON "locality_point" WHEN old."geometry" NOT NULL BEGIN
DELETE
FROM "rtree_locality_point_geometry"
WHERE id = OLD."fid"; END;


PRAGMA writable_schema=OFF;

COMMIT;
